if(page==='pets'&&p.pendingEgg){const h=p.pendingEgg;if(hatchStage!==h.taps){hatchStage=h.taps;hatchVisualTime=0}hatchVisualTime+=dt;const c=$('#petHatchCanvas');if(c)drawPetHatch(c.getContext('2d'),hatchPainter,PETS[h.id],h.taps,hatchVisualTime)}
