if(state.training&&!training){training=true;trainingStart=p.speed;lastMilestone=Math.floor(p.speed/10);begin('train');toast('TRAINING • walk off the belt to stop')}else if(!state.training&&training)stopTrain();$('#trainingHUD').hidden=!training;if(training){p.speed=Math.min(500,p.speed+trainingRate(p)*dt);const goal=zones.find(z=>speed(p)<z.speed);$('#trainingGain').textContent='+'+(p.speed-trainingStart).toFixed(1)+' SPEED'+(petBonus(p,'training')?' · PET +'+Math.round(petBonus(p,'training')*100)+'%':'');$('#trainingNext').textContent=goal?'NEXT CIRCUIT · '+Math.ceil(goal.speed-speed(p))+' TO GO':'ALL CIRCUITS UNLOCKED';$('#trainingFill').style.width=(goal?Math.min(100,speed(p)/goal.speed*100):100)+'%';if(Math.floor(p.speed/10)>lastMilestone){lastMilestone=Math.floor(p.speed/10);tone(660,.18,'triangle',.06);burst('#8bfbff',10)}if(state.step){tone(150+(stepCount++%4)*35,.05,'triangle',.025);if(stepCount%3===0)floatText('+'+(trainingRate(p)*.6).toFixed(1)+' SPEED')}}
