function compactPetEffect(){const a=PETS[p.buddy];if(!a)return 'Choose a pet';const names={speed:'MOVE',training:'TRAIN',income:'FPS',hatch:'HATCH',shield:'SHIELD'};if(a.kind==='skill')return FRONTIER[a.region].skill;return (names[a.kind]||'BOOST')+' '+(a.kind==='shield'?'×1':(a.kind==='hatch'?'-':'+')+Math.round(petBonus(p,a.kind)*100)+'%')}

function openOffice(focus=0){if(rolling||p.pendingPart!==null)return toast('Install the current part first.');if(p.run)return toast('Return to the workshop first.');if(farmViewing)hideFarm();if(inspecting)exitInspect();stopTrain();auto=false;view.reset();view.setOfficeView(true,focus);document.body.classList.add('officeViewing');page='office';$('#modal').hidden=false;$('#title').textContent=validComputer(p.buildParts)?'PLACE YOUR COMPUTER':'YOUR OFFICE';const ready=validComputer(p.buildParts),all=[p.equipped,...p.officePCs];$('#body').innerHTML=`<div class="officeSummary">${ready?'<b>8 / 8 COMPLETE</b><strong>+'+computerIncome(p.buildParts)+' FPS / s</strong>':'<b>'+all.filter(validComputer).length+' / 4 DESKS ONLINE</b>'}</div><div class="officeSlots">${all.map((ids,i)=>`<button data-desk="${i}" class="officeSlot"><b>DESK ${i+1}${i===0?' · MAIN':''}</b><div>${validComputer(ids)?partThumb(ids[0])+partThumb(ids[7]):'<span class="emptyDesk">＋</span>'}</div><small>${ids?'+'+computerIncome(ids)+' FPS / s':'EMPTY'}</small>${ready?'<strong>'+(ids?'REPLACE':'PLACE HERE')+'</strong>':''}</button>`).join('')}</div>`;$('#body').querySelectorAll('[data-desk]').forEach(b=>b.onclick=()=>{if(!ready){view.setOfficeView(true,+b.dataset.desk);return}if(!placeBuild(p,+b.dataset.desk))return;begin('pc-build');end();persist();models();partbar();actions();hud();win();burst();toast('COMPUTER PLACED · DESK '+(+b.dataset.desk+1));openOffice(+b.dataset.desk)})}
